import { useMemo, useState, type FormEvent } from 'react';
import { resolveNetwork, StellarService } from '@galaxy-kj/core-stellar-sdk';
import type { AccountInfo } from '@galaxy-kj/core-stellar-sdk';

const Home = () => {
  const stellar = useMemo(() => new StellarService(resolveNetwork('testnet')), []);
  const [publicKey, setPublicKey] = useState('');
  const [account, setAccount] = useState<AccountInfo | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleLookup = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setIsLoading(true);
    setError(null);
    setAccount(null);

    try {
      const accountInfo = await stellar.getAccountInfo(publicKey.trim());
      setAccount(accountInfo);
    } catch (lookupError) {
      setError(lookupError instanceof Error ? lookupError.message : 'Unable to load this account.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main className="min-h-screen bg-gradient-to-br from-purple-900 via-blue-900 to-indigo-900 px-4 py-12">
      <section className="mx-auto max-w-xl rounded-xl bg-white p-8 shadow-md">
        <p className="text-sm font-semibold uppercase tracking-wide text-indigo-500">{{PROJECT_NAME}}</p>
        <h1 className="mt-2 text-2xl font-bold text-gray-900">Stellar testnet account</h1>
        <p className="mt-2 text-gray-600">Look up a public account with the Galaxy Stellar SDK.</p>

        <form className="mt-6 space-y-4" onSubmit={handleLookup}>
          <label className="block text-sm font-medium text-gray-700" htmlFor="public-key">Public key</label>
          <input
            id="public-key"
            className="w-full rounded border border-gray-300 px-3 py-2"
            autoComplete="off"
            value={publicKey}
            onChange={(event) => setPublicKey(event.target.value)}
            placeholder="G..."
            required
          />
          <button
            className="w-full rounded bg-indigo-600 px-4 py-2 font-bold text-white hover:bg-indigo-700 disabled:opacity-50"
            disabled={isLoading}
            type="submit"
          >
            {isLoading ? 'Loading account...' : 'Look up account'}
          </button>
        </form>

        {error && <p className="mt-4 text-sm text-red-600" role="alert">{error}</p>}
        {account && (
          <section className="mt-6 rounded bg-gray-50 p-4" aria-live="polite">
            <h2 className="font-semibold text-gray-900">Account balances</h2>
            <ul className="mt-2 space-y-1 text-sm text-gray-700">
              {account.balances.map((balance) => (
                <li key={`${balance.asset}-${balance.limit ?? 'native'}`}>
                  {balance.balance} {balance.asset}
                </li>
              ))}
            </ul>
          </section>
        )}
      </section>
    </main>
  );
};

export default Home;

import '../styles/globals.css';
import type { AppProps } from 'next/app';

function MyApp({ Component, pageProps }: AppProps) {
  return <Component {...pageProps} />;
}

export default MyApp;

